mapper.update:
UPDATE kb_accounts
SET balance = balance - #{amount}
WHERE kb_account_id = #{kbAccountId}
  AND balance >= #{amount}

UPDATE kb_accounts
SET balance = balance + #{amount}
WHERE kb_account_id = #{kbAccountId}

UPDATE group_users
SET group_user_status = CASE
        WHEN current_deposit_amount - #{amount} < #{baseDepositAmount}
            THEN 'PENDING_DEPOSIT'
        ELSE group_user_status
    END,
    current_deposit_amount = current_deposit_amount - #{amount}
WHERE group_user_id = #{groupUserId}
  AND group_user_status IN ('ACTIVE', 'PENDING_DEPOSIT')
  AND current_deposit_amount >= #{amount}

UPDATE rounds
SET round_status = 'SETTLED'
WHERE round_id = #{roundId}
  AND round_status = 'WAITING_SETTLEMENT'
  AND end_date = #{endDate}
